/**
 * Content wave 3: the trials behind standard of care. Cancer standard-of-care rows cite these trials by acronym but
 * the corpus had no record (found by `npm run content:gaps -- --lists`, 22 Sept 2026). Ordered by the family burden
 * list in docs/CONTENT-ROADMAP.md (leukaemia, brain, childhood, lymphoma, gastric, pancreatic, sarcoma, anal).
 *
 * Sourcing rules. Every NCT id was resolved through the ClinicalTrials.gov v2 API and accepted only when the acronym
 * matches the registry's acronym field, its own study id (COG protocol numbers such as AALL1331 are the registry's
 * orgStudyId or a secondary id) or the official title; where the registry carries no acronym (MORPHO, IMpactMF) the
 * primary publication found on Europe PMC by NCT id names both. Phase, status, sponsor, enrolment and arms are the
 * registry's. Outcomes quote the reported figure with its endpoint and arm names from the registry results section
 * or the primary publication named in `source`; nothing is estimated. `enrolled` is the registry count unless
 * `enrolledBasis` says otherwise, with the registry figure in `enrolledNote`. Cancers, drugs and companies are
 * existing ids only; a drug with no record (deferasirox, epratuzumab) is named in the text and left out of `drugs`.
 * Raw responses are cached under /tmp/ctgov-cache and /tmp/europepmc-cache. Registered in src/data/index.ts as
 * trialsSocWave; `tldrZh` is folded by scripts/fold-zh.ts.
 *
 * SKIP list (acronyms from the gap list that do not resolve to one registry record, with the reason):
 *   Already in the corpus, missed by the gap tokeniser: HERIZON and GEA-01 (herizon-btc-302, herizon-gea-01),
 *   CLARITY (clarity-gastric01), STS 1001 (isg-sts-1001), ESCALaTE (de-escalate), EMPOWER (empower-cscc-1),
 *   PREOPANC (preopanc), CONTINUATION (proud-pv), OptimICE (optimice-pcr; the token is also the ASCENT-05 programme name).
 *   Registered only with UMIN (Japan), which is outside the networks this wave may query, so the acronym cannot be
 *   checked against a registry record: REGATTA (UMIN000001012), JCOG0912 (UMIN000003319), JCOG0802 (UMIN000002317),
 *   CREATE-X. GROINSS (the text cites GROINSS-V I, which has no ClinicalTrials.gov record; NCT01500512 is the separate
 *   GROINSS-V II observational study). PLATO ACT5 (ISRCTN88455282 only, no results and no primary publication by NCT id).
 *   REMORA (Japanese registry only). BEST4 (ISRCTN only, no publication yet). UK and German academic trials registered
 *   with ISRCTN only (ESPAC-4, CONKO-001, CAPP2) are written from the primary publication, which names the acronym and
 *   the ISRCTN id carried in `nct`.
 *   Not trials: AKT1, MLH1, KMT2A, FGFR2b, FGFR4, IGF-1R, INI1 (genes or biomarkers); NSAIDs, VeIP, COPDAC, EE-4A,
 *   DD-4A (regimens); PanNETs, NETs, VIPoma, CIN 3 (disease terms); CSI 23, CSI 36, ISRT 30, RFS 48 (doses and figures);
 *   MammaPrint, ThyroSeq (assays); NUV-868 (drug code); EpSSG (study group); EXPeRT (rare tumour registry).
 */
import type { TrialInput } from "@/lib/schema";

const asOf = "2026-09-22";
const ct = (nct: string) => ({ label: `ClinicalTrials.gov ${nct}`, url: `https://clinicaltrials.gov/study/${nct}` });
const results = (nct: string) => `https://clinicaltrials.gov/study/${nct}?tab=results`;
const doi = (d: string) => `https://doi.org/${d}`;
const tags = ["soc-trials"];
type T = Omit<TrialInput, "kind" | "asOf" | "tags">;
const t = (x: T): TrialInput => ({ kind: "trial", asOf, tags, ...x });

